package reconciliationnetting

type Item struct {
	ID       string
	Currency string
	Amount   int64
}

type Group struct {
	Internal []Item
	External []Item
}

func Reconcile(internal, external []Item) []Group {
	used := make([]bool, len(internal))
	var current, best []Group

	var allocate func(int)
	allocate = func(externalIndex int) {
		if externalIndex == len(external) {
			if len(current) > len(best) {
				best = append([]Group(nil), current...)
			}
			return
		}
		if len(current)+len(external)-externalIndex <= len(best) {
			return
		}

		target := external[externalIndex]
		var selected []int
		var subsets func(int, int64)
		subsets = func(internalIndex int, total int64) {
			if internalIndex == len(internal) {
				if len(selected) == 0 || total != target.Amount {
					return
				}

				items := make([]Item, len(selected))
				for index, selectedIndex := range selected {
					used[selectedIndex] = true
					items[index] = internal[selectedIndex]
				}
				current = append(current, Group{Internal: items, External: []Item{target}})
				allocate(externalIndex + 1)
				current = current[:len(current)-1]
				for _, selectedIndex := range selected {
					used[selectedIndex] = false
				}
				return
			}

			item := internal[internalIndex]
			if !used[internalIndex] && item.Currency == target.Currency {
				selected = append(selected, internalIndex)
				subsets(internalIndex+1, total+item.Amount)
				selected = selected[:len(selected)-1]
			}
			subsets(internalIndex+1, total)
		}

		subsets(0, 0)
		allocate(externalIndex + 1)
	}

	allocate(0)
	return best
}

