package reconciliationnetting

type Item struct {
	ID       string
	Currency string
	Amount   int64
}

type Group struct {
	Internal []Item
	External []Item
}

func Reconcile(internal, external []Item) []Group {
	var groups []Group
	used := make([]bool, len(internal))
	for _, externalItem := range external {
		indexes, ok := matchingSubset(internal, used, externalItem, 0, 0, nil)
		if !ok {
			continue
		}

		matched := make([]Item, len(indexes))
		for i, index := range indexes {
			used[index] = true
			matched[i] = internal[index]
		}
		groups = append(groups, Group{Internal: matched, External: []Item{externalItem}})
	}
	return groups
}

func matchingSubset(items []Item, used []bool, target Item, index int, total int64, selected []int) ([]int, bool) {
	if index == len(items) {
		return selected, len(selected) > 0 && total == target.Amount
	}

	if !used[index] && items[index].Currency == target.Currency {
		if match, ok := matchingSubset(items, used, target, index+1, total+items[index].Amount, append(selected, index)); ok {
			return match, true
		}
	}
	return matchingSubset(items, used, target, index+1, total, selected)
}

