package httplifecycle

import (
	"context"
	"io"
	"math"
)

var ErrTooLarge = io.ErrShortBuffer

func Decode(ctx context.Context, body io.ReadCloser, maxBytes int64) ([]byte, error) {
	defer body.Close()

	if err := ctx.Err(); err != nil {
		return nil, err
	}
	if maxBytes < 0 {
		return nil, ErrTooLarge
	}

	limit := maxBytes
	if limit < math.MaxInt64 {
		limit++
	}
	data, err := io.ReadAll(&io.LimitedReader{
		R: contextReader{ctx: ctx, reader: body},
		N: limit,
	})
	if err != nil {
		return nil, err
	}
	if int64(len(data)) > maxBytes {
		return nil, ErrTooLarge
	}
	return data, nil
}

type contextReader struct {
	ctx    context.Context
	reader io.Reader
}

func (r contextReader) Read(p []byte) (int, error) {
	if err := r.ctx.Err(); err != nil {
		return 0, err
	}
	return r.reader.Read(p)
}

