	"context"
	"errors"
	"sync"
)

func ProcessAll(ctx context.Context, items []int, limit int, process func(context.Context, int) error) error {
	if limit <= 0 {
		return errors.New("limit must be positive")
	}

	ctx, cancel := context.WithCancel(ctx)
	defer cancel()

	sem := make(chan struct{}, limit)
	var (
		wg         sync.WaitGroup
		errOnce    sync.Once
		processErr error
	)

schedule:
	for _, item := range items {
		select {
		case <-ctx.Done():
			break schedule
		case sem <- struct{}{}:
		}

		wg.Add(1)
		go func() {
			defer wg.Done()
			defer func() { <-sem }()

			if err := process(ctx, item); err != nil {
				errOnce.Do(func() {
					processErr = err
					cancel()
				})
			}
		}()
	}

	wg.Wait()
	if processErr != nil {
		return processErr
	}
	return ctx.Err()
}

