package racecounter

import "sync"

type Counter struct {
	mu       sync.Mutex
	accepted int
	posted   int
	version  int
}

func (c *Counter) Add() {
	c.mu.Lock()
	defer c.mu.Unlock()

	c.accepted++
	c.posted++
	c.version++
}

func (c *Counter) Snapshot() (accepted, posted, version int) {
	c.mu.Lock()
	defer c.mu.Unlock()

	return c.accepted, c.posted, c.version
}

