package moneyrounding

import "sort"

func Allocate(total int64, recipients []string) map[string]int64 {
	result := make(map[string]int64, len(recipients))
	if len(recipients) == 0 {
		return result
	}

	ordered := append([]string(nil), recipients...)
	sort.Strings(ordered)
	share := total / int64(len(ordered))
	remainder := total % int64(len(ordered))
	for i, recipient := range ordered {
		result[recipient] = share
		if int64(i) < remainder {
			result[recipient]++
		} else if int64(i) < -remainder {
			result[recipient]--
		}
	}
	return result
}

