package retryamplification

func Call(layers, attempts int, leaf func() error) error {
	if layers == 0 {
		return leaf()
	}
	var err error
	for range attempts {
		err = call(layers-1, leaf)
		if err == nil {
			return nil
		}
	}
	return err
}

func call(layers int, leaf func() error) error {
	if layers == 0 {
		return leaf()
	}
	return call(layers-1, leaf)
}

