func Reconcile(internal, external []Item) []Group {
	var groups []Group
	used := make([]bool, len(internal))

	for _, bankItem := range external {
		indexes, ok := matchingItems(internal, used, bankItem.Currency, bankItem.Amount, 0, 0, nil)
		if !ok {
			continue
		}

		matched := make([]Item, len(indexes))
		for index, internalIndex := range indexes {
			used[internalIndex] = true
			matched[index] = internal[internalIndex]
		}
		groups = append(groups, Group{Internal: matched, External: []Item{bankItem}})
	}
	return groups
}

func matchingItems(items []Item, used []bool, currency string, target, total int64, next int, selected []int) ([]int, bool) {
	if total == target && len(selected) > 0 {
		return selected, true
	}
	if next == len(items) {
		return nil, false
	}

	if !used[next] && items[next].Currency == currency {
		withItem := append(selected, next)
		if match, ok := matchingItems(items, used, currency, target, total+items[next].Amount, next+1, withItem); ok {
			return match, true
		}
	}

	return matchingItems(items, used, currency, target, total, next+1, selected)
}

