		indices, ok := matchingSubset(internal, used, externalItem.Currency, externalItem.Amount)
		if !ok {
			continue
		}

		matched := make([]Item, len(indices))
		for i, index := range indices {
			used[index] = true
			matched[i] = internal[index]
		}
		groups = append(groups, Group{Internal: matched, External: []Item{externalItem}})
	}
	return groups
}

func matchingSubset(items []Item, used []bool, currency string, amount int64) ([]int, bool) {
	var search func(int, int64, []int) ([]int, bool)
	search = func(start int, total int64, selected []int) ([]int, bool) {
		if len(selected) > 0 && total == amount {
			return selected, true
		}
		for index := start; index < len(items); index++ {
			if used[index] || items[index].Currency != currency {
				continue
			}
			if match, ok := search(index+1, total+items[index].Amount, append(selected, index)); ok {
				return match, true
			}
		}
		return nil, false
	}

	return search(0, 0, nil)
}

