import "sync"

type Counter struct {
	mu       sync.RWMutex
	accepted int
	posted   int
	version  int
}

func (c *Counter) Add() {
	c.mu.Lock()
	defer c.mu.Unlock()

	c.accepted++
	c.posted++
	c.version++
}

func (c *Counter) Snapshot() (accepted, posted, version int) {
	c.mu.RLock()
	defer c.mu.RUnlock()

	return c.accepted, c.posted, c.version
}

