package httplifecycle

import (
	"context"
	"io"
)

var ErrTooLarge = io.ErrShortBuffer

func Decode(ctx context.Context, body io.ReadCloser, maxBytes int64) ([]byte, error) {
	defer body.Close()

	if err := ctx.Err(); err != nil {
		return nil, err
	}
	if maxBytes < 0 {
		return nil, ErrTooLarge
	}

	stopClose := context.AfterFunc(ctx, func() { _ = body.Close() })
	defer stopClose()

	limited := &io.LimitedReader{R: body, N: maxBytes}
	data, err := io.ReadAll(limited)
	if ctxErr := ctx.Err(); ctxErr != nil {
		return nil, ctxErr
	}
	if err != nil {
		return nil, err
	}

	var extra [1]byte
	n, err := body.Read(extra[:])
	if ctxErr := ctx.Err(); ctxErr != nil {
		return nil, ctxErr
	}
	if n != 0 {
		return nil, ErrTooLarge
	}
	if err != nil && err != io.EOF {
		return nil, err
	}

	return data, nil
}

