func ProcessAll(ctx context.Context, items []int, limit int, process func(context.Context, int) error) error {
	if limit <= 0 {
		return errors.New("process concurrency limit must be positive")
	}

	ctx, cancel := context.WithCancel(ctx)
	defer cancel()

	jobs := make(chan int)
	var workers sync.WaitGroup
	var errOnce sync.Once
	var processErr error

	workerCount := min(limit, len(items))
	workers.Add(workerCount)
	for range workerCount {
		go func() {
			defer workers.Done()
			for item := range jobs {
				if err := process(ctx, item); err != nil {
					errOnce.Do(func() {
						processErr = err
						cancel()
					})
				}
			}
		}()
	}

	for _, item := range items {
		select {
		case jobs <- item:
		case <-ctx.Done():
			close(jobs)
			workers.Wait()
			if processErr != nil {
				return processErr
			}
			return ctx.Err()
		}
	}
	close(jobs)
	workers.Wait()
	if processErr != nil {
		return processErr
	}
	if err := ctx.Err(); err != nil {
		return err
	}
	return nil
}

