func Allocate(total int64, recipients []string) map[string]int64 {
	result := make(map[string]int64, len(recipients))
	if len(recipients) == 0 {
		return result
	}

	base := total / int64(len(recipients))
	residualRecipient := recipients[0]
	for _, recipient := range recipients {
		result[recipient] = base
		if recipient < residualRecipient {
			residualRecipient = recipient
		}
	}
	result[residualRecipient] += total - base*int64(len(recipients))
	return result
}

